#include <bits/stdc++.h>
using namespace std;
const int MX = 200005;
int spf[MX];
int cnt[MX];
vector<int> primesOf(int x) {
    vector<int> ps;
    while (x > 1) { int p = spf[x]; ps.push_back(p); while (x % p == 0) x /= p; }
    return ps;
}
int main() {
    for (int i = 2; i < MX; i++)
        if (!spf[i]) for (int j = i; j < MX; j += i) if (!spf[j]) spf[j] = i;
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<int> a(n), b(n);
        for (auto &x : a) scanf("%d", &x);
        for (auto &x : b) scanf("%d", &x);  // easy version: all b_i = 1
        vector<int> touched;
        for (int v : a) for (int p : primesOf(v)) { if (cnt[p]++ == 0) touched.push_back(p); }
        bool zero = false;
        for (int p : touched) if (cnt[p] >= 2) zero = true;
        int ans = 2;
        if (zero) ans = 0;
        else for (int v : a) for (int p : primesOf(v + 1)) if (cnt[p] >= 1) ans = min(ans, 1);
        printf("%d\n", ans);
        for (int p : touched) cnt[p] = 0;
    }
}

