#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    const int L = 25;
    long long p3[L];
    p3[0] = 1;
    for (int i = 1; i < L; i++) p3[i] = p3[i - 1] * 3;
    while (t--) {
        long long n, k; scanf("%lld %lld", &n, &k);
        vector<long long> cnt(L, 0);
        long long s = 0, v = n;
        for (int x = 0; v > 0; x++, v /= 3) { cnt[x] = v % 3; s += cnt[x]; }
        if (s > k) { puts("-1"); continue; }
        long long B = (k - s) / 2;           // each split of a 3^x deal adds 2 deals, saves 3^(x-1)
        for (int x = L - 1; x >= 1; x--) {   // split the largest deals first
            long long tk = min(B, cnt[x]);
            cnt[x] -= tk; cnt[x - 1] += 3 * tk; B -= tk;
        }
        long long cost = 0;
        for (int x = 0; x < L; x++) {
            if (!cnt[x]) continue;
            long long c = 3 * p3[x];                   // 3^(x+1)
            if (x >= 1) c += x * p3[x - 1];            // x * 3^(x-1)
            cost += cnt[x] * c;
        }
        printf("%lld\n", cost);
    }
}

