int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; long long m, k;
        scanf("%d %lld %lld", &n, &m, &k);
        vector<long long> a(n);
        for (auto &x : a) scanf("%lld", &x);
        sort(a.begin(), a.end());
        // cost = sum a_i x_i + (k^2 - sum x_i^2) / 2, so fill the cheapest days to the limit m first
        long long rem = k, sumAx = 0, sumX2 = 0;
        for (int i = 0; i < n && rem > 0; i++) {
            long long take = min(m, rem);
            sumAx += a[i] * take;
            sumX2 += take * take;
            rem -= take;
        }
        printf("%lld\n", sumAx + (k * k - sumX2) / 2);
    }
}

