        vector<long long> S(n + 1, 0);
        for (int i = 0; i < n; i++) S[i + 1] = S[i] + a[i];
        int best = 0;                        // keep m elements: need sum >= sum of m smallest primes
        for (int m = n; m >= 1; m--) if (S[m] >= P[m]) { best = m; break; }
        printf("%d\n", n - best);
    }
}

