int main() {
    int q; scanf("%d", &q);
    while (q--) {
        int n; scanf("%d", &n);
        vector<int> a(n);
        for (auto &x : a) scanf("%d", &x);
        int pos = 0;
        while (pos < n) {
            int j = pos;
            for (int k = pos; k < n; k++) if (a[k] < a[j]) j = k;   // min of the free suffix
            if (j == pos) { pos++; continue; }
            int v = a[j];                                      // bubble it left using ops pos..j-1
            for (int k = j; k > pos; k--) a[k] = a[k - 1];
            a[pos] = v;
            pos = j;                                           // ops pos..j-1 are spent; position j is still free
        }
        for (int i = 0; i < n; i++) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');
    }
}

