// card = rank char + suit char, e.g. "9S"; rank order is the character order '2'..'9'
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        char tb[8]; scanf("%s", tb);
        char trump = tb[0];
        map<char, vector<string>> bySuit;
        for (int i = 0; i < 2 * n; i++) { char s[8]; scanf("%s", s); bySuit[s[1]].push_back(s); }
        for (auto &kv : bySuit) sort(kv.second.begin(), kv.second.end());
        vector<string> T = bySuit[trump];
        vector<string> lone;                     // one card from each odd non-trump suit
        vector<pair<string, string>> out;        // (attacker, beater)
        for (auto &kv : bySuit) {
            if (kv.first == trump) continue;
            auto L = kv.second;
            if (L.size() % 2) { lone.push_back(L.back()); L.pop_back(); }
            for (size_t i = 0; i + 1 < L.size(); i += 2) out.push_back({L[i], L[i + 1]});  // same suit: higher beats lower
        }
        if (lone.size() > T.size()) { puts("IMPOSSIBLE"); continue; }
        for (auto &x : lone) { out.push_back({x, T.back()}); T.pop_back(); }            // trump beats non-trump
        for (size_t i = 0; i + 1 < T.size(); i += 2) out.push_back({T[i], T[i + 1]});  // trumps: higher beats lower
        for (auto &p : out) printf("%s %s\n", p.first.c_str(), p.second.c_str());
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int T; scanf("%d", &T);
    while (T--) {
        int n, m; scanf("%d %d", &n, &m);
        multiset<long long> S;
        for (int i = 0; i < n; i++) { long long x; scanf("%lld", &x); S.insert(x); }
        vector<long long> b(m), c(m);
        for (auto &x : b) scanf("%lld", &x);
        for (auto &x : c) scanf("%lld", &x);
        vector<int> pos, zero;
        for (int i = 0; i < m; i++) (c[i] > 0 ? pos : zero).push_back(i);
        sort(pos.begin(), pos.end(), [&](int x, int y) { return b[x] < b[y]; });
        int kills = 0;
        // phase 1: monsters that refund a sword never lose a sword, so kill them first
        for (int i : pos) {
            auto it = S.lower_bound(b[i]);
            if (it == S.end()) continue;
            long long x = *it;
            S.erase(it);
            S.insert(max(x, c[i]));
            kills++;
        }
        // phase 2: one-shot monsters (c = 0), greedy matching of sorted swords to sorted monsters
        vector<long long> bz;
        for (int i : zero) if (c[i] == 0) bz.push_back(b[i]);
        sort(bz.begin(), bz.end());
        size_t j = 0;
        for (long long x : S) if (j < bz.size() && bz[j] <= x) { kills++; j++; }
        printf("%d\n", kills);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; long long k; scanf("%d %lld", &n, &k);
        vector<long long> a(n);
        for (auto &x : a) scanf("%lld", &x);
        vector<long long> S = a;
        sort(S.begin(), S.end());
        S.erase(unique(S.begin(), S.end()), S.end());
        long long sz = S.size();
        auto inS = [&](long long x) { return binary_search(S.begin(), S.end(), x); };
        vector<long long> G;                      // b whose multiples <= k are all present
        unordered_set<long long> covered, nonmin; // covered: has a G-divisor; nonmin: has a smaller G-divisor
        for (long long v : S) {                   // G is a subset of S (b itself is a multiple of b)
            long long q = k / v;
            if (q > sz) continue;                 // too many multiples to all be in a
            bool ok = true;
            for (long long j = 1; j <= q && ok; j++) if (!inS(j * v)) ok = false;
            if (!ok) continue;
            G.push_back(v);
            for (long long j = 1; j <= q; j++) {
                covered.insert(j * v);
                if (j >= 2) nonmin.insert(j * v);
            }
        }
        bool all = true;
        for (long long x : S) if (!covered.count(x)) { all = false; break; }
        if (!all) { puts("-1"); continue; }
        vector<long long> M;                      // minimal elements of G are forced and sufficient
        for (long long g : G) if (!nonmin.count(g)) M.push_back(g);
        sort(M.begin(), M.end());
        printf("%zu\n", M.size());
        for (size_t i = 0; i < M.size(); i++) printf("%lld%c", M[i], i + 1 == M.size() ? '\n' : ' ');
    }
}

