    while (t--) {
        int n; scanf("%d", &n);
        vector<long long> l(n), r(n), c(n);
        for (auto &x : l) scanf("%lld", &x);
        for (auto &x : r) scanf("%lld", &x);
        for (auto &x : c) scanf("%lld", &x);
        vector<pair<long long, int>> ev;          // (position, 0 = left end, 1 = right end)
        for (auto x : l) ev.push_back({x, 0});
        for (auto x : r) ev.push_back({x, 1});
        sort(ev.begin(), ev.end());
        vector<long long> st, len;
        for (auto &e : ev) {
            if (e.second == 0) st.push_back(e.first);
            else { len.push_back(e.first - st.back()); st.pop_back(); }  // nearest open left end
        }
        sort(len.begin(), len.end());             // shortest interval gets the largest rate
        sort(c.rbegin(), c.rend());
        long long ans = 0;
        for (int i = 0; i < n; i++) ans += c[i] * len[i];
        printf("%lld\n", ans);
    }
}

