#include <bits/stdc++.h>
using namespace std;
// Records (prefix minima) form a chain 1..; sum = sum(records) + (n - #records) when non-records hang off node 1.
// Extra over base n is sum of (r - 1) over chosen records, which is any value in [0, n(n-1)/2].
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        long long n, m; scanf("%lld %lld", &n, &m);
        long long E = m - n, maxE = n * (n - 1) / 2;
        if (E < 0 || E > maxE) { puts("-1"); continue; }
        vector<char> inR(n + 1, 0);
        inR[1] = 1;
        for (long long v = n; v >= 2; v--)       // greedy subset of {v-1} summing to E
            if (E >= v - 1) { inR[v] = 1; E -= v - 1; }
        vector<long long> rec;
        for (long long v = n; v >= 1; v--) if (inR[v]) rec.push_back(v);
        printf("%lld\n", rec[0]);                 // root = largest record
        for (size_t i = 0; i + 1 < rec.size(); i++) printf("%lld %lld\n", rec[i], rec[i + 1]);
        for (long long v = 2; v <= n; v++) if (!inR[v]) printf("%lld 1\n", v);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; long long k; scanf("%d %lld", &n, &k);
        vector<long long> freq(n + 1, 0), pre(n + 1, 0);
        for (int i = 0; i < n; i++) { int x; scanf("%d", &x); freq[x]++; }
        for (int v = 1; v <= n; v++) pre[v] = pre[v - 1] + freq[v];
        // g is achievable iff #elements < 4g that are not multiples of g is <= k
        // (non-multiples >= 4g can be split into multiples of g without any erase)
        for (long long g = n; g >= 1; g--) {
            long long hi = min(4 * g - 1, (long long)n);
            long long mult = 0;
            for (long long j = 1; j <= 3; j++) { long long v = j * g; if (v <= n) mult += freq[v]; }
            long long bad = pre[hi] - mult;
            if (bad <= k) { printf("%lld\n", g); break; }
        }
    }
}

