using namespace std;
// Only the top bit h of T = XOR(a_i ^ b_i) matters. Indices with bit h of a_i != bit h of b_i are the
// only real choices; the owner of the last such index decides the result.
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<int> a(n), b(n);
        for (auto &x : a) scanf("%d", &x);
        for (auto &x : b) scanf("%d", &x);
        int T = 0;
        for (int i = 0; i < n; i++) T ^= a[i] ^ b[i];
        if (T == 0) { puts("Tie"); continue; }
        int h = 31 - __builtin_clz(T);
        int last = -1;                       // 1-indexed index of the last choice index
        for (int i = 0; i < n; i++)
            if (((a[i] >> h) & 1) != ((b[i] >> h) & 1)) last = i + 1;
        puts(last % 2 == 1 ? "Ajisai" : "Mai");   // odd index: Ajisai moves there
    }
}

#include <bits/stdc++.h>
using namespace std;
// L = count of -1, R = count of -2, X = distinct positive requests (all <= m).
// Only -1 people: min(m, L+D). Only -2: min(m, R+D).
// Mixed: first a request p is seated, then the -1 chain fills non-requested seats left of p
// and the -2 chain fills non-requested seats right of p (requests on either side are placed in order).
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, m; scanf("%d %d", &n, &m);
        long long L = 0, R = 0;
        vector<int> X;
        for (int i = 0; i < n; i++) {
            int x; scanf("%d", &x);
            if (x == -1) L++;
            else if (x == -2) R++;
            else X.push_back(x);
        }
        sort(X.begin(), X.end());
        X.erase(unique(X.begin(), X.end()), X.end());
        long long D = X.size();
        long long ans = max(min((long long)m, L + D), min((long long)m, R + D));
        for (long long i = 0; i < D; i++) {
            long long p = X[i];
            long long leftFree = (p - 1) - i;               // seats left of p not requested
            long long rightFree = (m - p) - (D - 1 - i);    // seats right of p not requested
            ans = max(ans, D + min(L, leftFree) + min(R, rightFree));
        }
        printf("%lld\n", ans);
    }
}

