using namespace std;
// Splitting and merging never change the sequence of "atoms", where x = q * m^e (m does not divide q)
// contributes q repeated m^e times. Compare the run-length encodings of the two atom sequences.
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; long long m; scanf("%d %lld", &n, &m);
        auto runs = [&](int len) {
            vector<pair<long long, long long>> R;     // (atom value, count)
            for (int i = 0; i < len; i++) {
                long long x; scanf("%lld", &x);
                long long cnt = 1;
                while (x % m == 0) { x /= m; cnt *= m; }
                if (!R.empty() && R.back().first == x) R.back().second += cnt;
                else R.push_back({x, cnt});
            }
            return R;
        };
        auto A = runs(n);
        int k; scanf("%d", &k);
        auto B = runs(k);
        puts(A == B ? "Yes" : "No");
    }
}

#include <bits/stdc++.h>
using namespace std;
// Sorted a. Optimal bags are contiguous blocks X=[0..i], Y=[i+1..j], Z=[j+1..n-1]; the score depends
// on which block is the "middle" bag. Three families (0-indexed):
//   middle = Y:  a[j+1] - a[i]                     -> best a[n-1] - a[0]
//   middle = Z:  (a[k] - a[0]) + (a[k] - a[k-1]),  k >= 2
//   middle = X:  (a[i+1] - a[i]) + (a[n-1] - a[i]), i <= n-3
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<long long> a(n);
        for (auto &x : a) scanf("%lld", &x);
        sort(a.begin(), a.end());
        long long best = a[n - 1] - a[0];
        for (int k = 2; k < n; k++) best = max(best, (a[k] - a[0]) + (a[k] - a[k - 1]));
        for (int i = 0; i + 2 < n; i++) best = max(best, (a[i + 1] - a[i]) + (a[n - 1] - a[i]));
        printf("%lld\n", best);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<int> a(n + 1), b(n + 1), sigma(n + 1);
        for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
        for (int i = 1; i <= n; i++) scanf("%d", &b[i]);
        for (int i = 1; i <= n; i++) sigma[a[i]] = b[i];
        bool ok = true;
        int fixedCnt = 0;
        for (int u = 1; u <= n; u++) {
            if (sigma[sigma[u]] != u) ok = false;
            if (sigma[u] == u) fixedCnt++;
        }
        if (!ok || fixedCnt > 1) { puts("-1"); continue; }
        // target layout: mirror positions hold (u,v) and (v,u); a single fixed point goes to the middle
        vector<int> Ta(n + 1), Tb(n + 1);
        int pos = 1;
        for (int u = 1; u <= n; u++) {
            int v = sigma[u];
            if (v > u) {                       // 2-cycle {u,v}
                Ta[pos] = u; Tb[pos] = v;
                Ta[n + 1 - pos] = v; Tb[n + 1 - pos] = u;
                pos++;
            } else if (v == u) {               // fixed point, middle only
                Ta[(n + 1) / 2] = u; Tb[(n + 1) / 2] = u;
            }
        }
        // current pairs (a[p], b[p]); where[u] = position holding the pair whose first element is u
        vector<int> where(n + 1);
        for (int p = 1; p <= n; p++) where[a[p]] = p;
        vector<pair<int, int>> ops;
        for (int p = 1; p <= n; p++) {
            int q = where[Ta[p]];
            if (q != p) {
                swap(a[p], a[q]); swap(b[p], b[q]);
                where[a[p]] = p; where[a[q]] = q;
                ops.push_back({p, q});
            }
        }
        printf("%zu\n", ops.size());
        for (auto &o : ops) printf("%d %d\n", o.first, o.second);
    }
}

