#include <bits/stdc++.h>
using namespace std;
// A palindrome of length L needs floor(L/2) equal-value pairs, plus one centre if L is odd.
// P = total pairs of 0s and 1s; S = leftover single chars. A broken pair gives two centres.
// Take strings by increasing length while the pair budget allows.
int main() {
    int q; scanf("%d", &q);
    while (q--) {
        int n; scanf("%d", &n);
        vector<int> len(n);
        long long c0 = 0, c1 = 0;
        char buf[64];
        for (int i = 0; i < n; i++) {
            scanf("%s", buf);
            len[i] = strlen(buf);
            for (int j = 0; buf[j]; j++) (buf[j] == '0' ? c0 : c1)++;
        }
        long long P = c0 / 2 + c1 / 2, S = c0 % 2 + c1 % 2;
        sort(len.begin(), len.end());
        long long F = 0, E = 0;
        int cnt = 0;
        for (int L : len) {
            long long nF = F + L / 2, nE = E + L % 2;
            long long broken = max(0LL, nE - S);
            long long need = nF + (broken + 1) / 2;
            if (need <= P) { F = nF; E = nE; cnt++; }
            else break;
        }
        printf("%d\n", cnt);
    }
}

