using namespace std;
// score = (#W) + (#adjacent WW pairs). Fill internal L-gaps (between two W's) shortest first;
// each full gap of length g adds g wins and g+1 pairs. Leftover flips add 2 each once a W exists.
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, k; scanf("%d %d", &n, &k);
        static char buf[200005];
        scanf("%s", buf);
        string s = buf;
        int countL = count(s.begin(), s.end(), 'L');
        if (k >= countL) { printf("%d\n", 2 * n - 1); continue; }
        long long w = count(s.begin(), s.end(), 'W');
        if (w == 0) { printf("%d\n", k >= 1 ? 2 * k - 1 : 0); continue; }
        long long pairs = 0;
        for (int i = 0; i + 1 < n; i++) if (s[i] == 'W' && s[i + 1] == 'W') pairs++;
        vector<int> gaps;
        int first = s.find('W'), last = s.rfind('W');
        for (int i = first; i <= last;) {
            if (s[i] == 'W') { i++; continue; }
            int j = i;
            while (j <= last && s[j] == 'L') j++;
            gaps.push_back(j - i);
            i = j;
        }
        sort(gaps.begin(), gaps.end());
        long long rem = k, filled = 0;
        for (int g : gaps) {
            if (rem >= g) { w += g; pairs += g + 1; rem -= g; filled += g; }
            else break;
        }
        long long leftL = countL - filled;
        long long extra = min(rem, leftL);
        printf("%lld\n", w + pairs + 2 * extra);
    }
}

