#include <bits/stdc++.h>
using namespace std;
// Optimal coloured path: height at gap i is min(i, 2n-i, cap_i) with cap_i = k or k-1 by parity.
// Group gaps by T = min(i, 2n-i): for T < k they contribute T*g, for T >= k they contribute k*g or (k-1)*g
// depending on whether T and k have the same parity.
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        int N = 2 * n;
        vector<long long> a(N + 1);
        for (int i = 1; i <= N; i++) scanf("%lld", &a[i]);
        vector<long long> Wt(n + 2, 0);
        for (int i = 1; i <= N - 1; i++) {
            long long g = a[i + 1] - a[i];
            int T = min(i, N - i);
            Wt[T] += g;
        }
        // suffix sums split by parity of T
        vector<vector<long long>> SS(2, vector<long long>(n + 3, 0));
        for (int T = n; T >= 1; T--) {
            for (int p = 0; p < 2; p++) SS[p][T] = SS[p][T + 1];
            SS[T % 2][T] += Wt[T];
        }
        long long PA = 0;   // sum over T < k of T * Wt[T]
        for (int k = 1; k <= n; k++) {
            if (k >= 2) PA += (long long)(k - 1) * Wt[k - 1];
            long long G = SS[k % 2][k];
            long long H = SS[(k + 1) % 2][k];
            long long ans = PA + (long long)k * G + (long long)(k - 1) * H;
            printf("%lld%c", ans, k == n ? '\n' : ' ');
        }
    }
}

