// t_i = next(s_i) on a 26-letter circle. Choose the circle greedily: for each new letter c in t,
// give it the smallest image d that is unused and does not close a cycle early.
int main() {
    int T; scanf("%d", &T);
    while (T--) {
        int n; scanf("%d", &n);
        static char buf[100005];
        scanf("%s", buf);
        int pi[26], inv[26];
        memset(pi, -1, sizeof pi); memset(inv, -1, sizeof inv);
        int edges = 0;
        string s(n, 'a');
        for (int i = 0; i < n; i++) {
            int c = buf[i] - 'a';
            if (pi[c] == -1) {
                int h = c;                       // head of the chain that ends at c
                while (inv[h] != -1) h = inv[h];
                int chosen = -1;
                for (int d = 0; d < 26 && chosen < 0; d++) {
                    if (inv[d] != -1) continue;
                    if (d == h && edges < 25) continue;   // would close a short cycle
                    chosen = d;
                }
                pi[c] = chosen; inv[chosen] = c; edges++;
            }
            s[i] = 'a' + pi[c];
        }
        printf("%s\n", s.c_str());
    }
}

