// A domino always has one B and one W. Row balance only involves vertical dominoes and needs an even
// count between each pair of consecutive rows; column balance only involves horizontal dominoes.
// Alternate colours along each such group so each group splits evenly.
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, m; scanf("%d %d", &n, &m);
        vector<string> g(n);
        static char buf[600];
        for (int i = 0; i < n; i++) { scanf("%s", buf); g[i] = buf; }
        vector<string> res = g;
        bool ok = true;
        // vertical dominoes grouped by the cut between rows r and r+1
        for (int r = 0; r + 1 < n && ok; r++) {
            vector<int> cols;
            for (int c = 0; c < m; c++) if (g[r][c] == 'U') cols.push_back(c);
            if (cols.size() % 2) { ok = false; break; }
            for (size_t k = 0; k < cols.size(); k++) {
                int c = cols[k];
                res[r][c] = (k % 2 == 0) ? 'B' : 'W';
                res[r + 1][c] = (k % 2 == 0) ? 'W' : 'B';
            }
        }
        // horizontal dominoes grouped by the cut between columns c and c+1
        for (int c = 0; c + 1 < m && ok; c++) {
            vector<int> rows;
            for (int r = 0; r < n; r++) if (g[r][c] == 'L') rows.push_back(r);
            if (rows.size() % 2) { ok = false; break; }
            for (size_t k = 0; k < rows.size(); k++) {
                int r = rows[k];
                res[r][c] = (k % 2 == 0) ? 'B' : 'W';
                res[r][c + 1] = (k % 2 == 0) ? 'W' : 'B';
            }
        }
        if (!ok) { puts("-1"); continue; }
        for (int r = 0; r < n; r++) puts(res[r].c_str());
    }
}

#include <bits/stdc++.h>
