// Target T = most frequent value. Each non-T element needs one op, and a neighbour equal to T makes
// it equal in one op, so spread outward from one T position.
int main() {
    int n; scanf("%d", &n);
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    map<long long, int> cnt;
    for (auto x : a) cnt[x]++;
    long long T = a[0]; int best = 0;
    for (auto &kv : cnt) if (kv.second > best) { best = kv.second; T = kv.first; }
    int p = 0;
    while (a[p] != T) p++;
    vector<array<int, 3>> ops;
    auto fix = [&](int i, int j) {          // element i (0-based) fixed using neighbour j (already T)
        if (a[i] == T) return;
        int type = (a[i] < T) ? 1 : 2;
        ops.push_back({type, i + 1, j + 1});
        a[i] = T;
    };
    for (int i = p - 1; i >= 0; i--) fix(i, i + 1);
    for (int i = p + 1; i < n; i++) fix(i, i - 1);
    printf("%zu\n", ops.size());
    for (auto &o : ops) printf("%d %d %d\n", o[0], o[1], o[2]);
}

