// 0 and 2 can never swap, so their relative order is fixed. 1 can pass both. Put every 1 right after
// the zeros that precede the first 2 (the zeros before the first 2 are the only ones 1 can precede).
int main() {
    static char buf[100005];
    scanf("%s", buf);
