    string seq;                            // the fixed subsequence of 0s and 2s
    int ones = 0;
    for (char c : s) { if (c == '1') ones++; else seq.push_back(c); }
    size_t firstTwo = seq.find('2');
    size_t zerosBefore = (firstTwo == string::npos) ? seq.size() : firstTwo;
    string out = seq.substr(0, zerosBefore) + string(ones, '1') + seq.substr(zerosBefore);
    printf("%s\n", out.c_str());
}

#include <bits/stdc++.h>
using namespace std;
// Each vertex must see only lower-or-equal neighbours or only higher-or-equal ones, and an equal neighbour
// forces degree 1. So the best graph is a complete bipartite split at a strict altitude gap (k*(n-k)),
// or a matching of n/2 edges when all altitudes are equal.
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<long long> a(n);
        for (auto &x : a) scanf("%lld", &x);
        sort(a.begin(), a.end());
        long long best = n / 2;
        for (int k = 1; k < n; k++)
            if (a[k - 1] < a[k]) best = max(best, (long long)k * (n - k));
        printf("%lld\n", best);
    }
}
